create table if not exists public.post_plan_relief_pool(plan_id uuid not null references public.post_plans(id) on delete cascade,personnel_id uuid not null references public.personnel(id),priority integer not null default 1,created_at timestamptz not null default now(),primary key(plan_id,personnel_id));
alter table public.post_plan_relief_pool enable row level security;
drop policy if exists post_plan_relief_pool_staff_read on public.post_plan_relief_pool;create policy post_plan_relief_pool_staff_read on public.post_plan_relief_pool for select to authenticated using(public.current_user_role() in('ADMIN','RRHH','OPERACIONES','SUPERVISOR'));
create or replace function public.provica_set_plan_primary(p_slot uuid,p_primary uuid)returns void language plpgsql security definer set search_path=public as $$begin if current_user_role() not in('ADMIN','OPERACIONES')then raise exception 'No autorizado';end if;if p_primary is not null and not exists(select 1 from personnel where id=p_primary and active and personnel_type='OPERATIVO' and intended_role='GUARDIA')then raise exception 'Titular invalido';end if;update post_plan_slots set primary_personnel_id=p_primary,relief_personnel_id=null where id=p_slot;if not found then raise exception 'Cajon inexistente';end if;end$$;
create or replace function public.provica_set_plan_relief_pool(p_plan uuid,p_personnel uuid,p_enabled boolean)returns void language plpgsql security definer set search_path=public as $$begin if current_user_role() not in('ADMIN','OPERACIONES')then raise exception 'No autorizado';end if;if p_enabled then if exists(select 1 from post_plan_slots where plan_id=p_plan and primary_personnel_id=p_personnel)then raise exception 'Un titular no puede estar en la bolsa de relevos';end if;insert into post_plan_relief_pool(plan_id,personnel_id)select p_plan,p_personnel where exists(select 1 from personnel where id=p_personnel and active and personnel_type='OPERATIVO' and intended_role='GUARDIA')on conflict do nothing;else delete from post_plan_relief_pool where plan_id=p_plan and personnel_id=p_personnel;end if;end$$;
create or replace function public.provica_generate_post_plan(p_plan uuid)returns jsonb language plpgsql security definer set search_path=public as $$declare pl post_plans%rowtype;sl post_plan_slots%rowtype;d date;a timestamptz;b timestamptz;who uuid;prof uuid;n int:=0;r int:=0;idx int;begin if current_user_role() not in('ADMIN','OPERACIONES')then raise exception 'No autorizado';end if;select * into pl from post_plans where id=p_plan and active for update;if not found then raise exception 'Plan inexistente';end if;if exists(select 1 from post_plan_slots where plan_id=p_plan and primary_personnel_id is null)then raise exception 'Asigne todos los titulares';end if;if not exists(select 1 from post_plan_relief_pool where plan_id=p_plan)then raise exception 'Agregue relevos';end if;delete from shifts where plan_slot_id in(select id from post_plan_slots where plan_id=p_plan)and status='PROGRAMADO' and starts_at>now();for sl in select * from post_plan_slots where plan_id=p_plan order by slot_order loop d:=pl.start_date;idx:=0;while d<=pl.end_date loop a:=(d::text||' '||sl.start_time::text)::timestamp at time zone 'America/Guayaquil';b:=a+make_interval(hours=>sl.duration_hours);if a>now()then if(idx%(sl.work_days+sl.rest_days))<sl.work_days then who:=sl.primary_personnel_id;else r:=r+1;who:=null;select rp.personnel_id into who from post_plan_relief_pool rp where rp.plan_id=p_plan and not exists(select 1 from shifts x where x.personnel_id=rp.personnel_id and x.status<>'CANCELADO' and x.starts_at<b and x.ends_at>a)order by(select count(*) from shifts z where z.personnel_id=rp.personnel_id and z.plan_slot_id in(select id from post_plan_slots where plan_id=p_plan)),rp.priority,rp.created_at limit 1;if who is null then raise exception 'Cobertura insuficiente para cajon % el %',sl.slot_order,d;end if;end if;if exists(select 1 from shifts where personnel_id=who and status<>'CANCELADO' and starts_at<b and ends_at>a)then raise exception 'Conflicto para % el %',(select person_code from personnel where id=who),d;end if;select profile_id into prof from personnel where id=who;insert into shifts(guard_post_id,guard_id,personnel_id,starts_at,ends_at,status,plan_slot_id)values(pl.guard_post_id,prof,who,a,b,'PROGRAMADO',sl.id);n:=n+1;end if;d:=d+1;idx:=idx+1;end loop;end loop;return jsonb_build_object('shifts_created',n,'relief_shifts',r,'coverage_percent',100);end$$;
revoke all on function public.provica_set_plan_primary(uuid,uuid) from public;revoke all on function public.provica_set_plan_relief_pool(uuid,uuid,boolean) from public;revoke all on function public.provica_generate_post_plan(uuid) from public;grant execute on function public.provica_set_plan_primary(uuid,uuid) to authenticated;grant execute on function public.provica_set_plan_relief_pool(uuid,uuid,boolean) to authenticated;grant execute on function public.provica_generate_post_plan(uuid) to authenticated;select pg_notify('pgrst','reload schema');